/* databahn.c */
void Databahn_Init(void)
{
	unsigned int i;
	unsigned int ddr_version;
	unsigned int tsel_feed;
	unsigned int data_e_sel;
	unsigned int ocd_pu_clk;
	unsigned int ocd_pd_clk;
	unsigned int ocd_pu_cmd;
	unsigned int ocd_pd_cmd;
	unsigned int dfi_cmd_control;
	unsigned int vref_set;
	unsigned int ddr_vref_en;
	unsigned int cwl;
	unsigned int encry_delay;
	unsigned char ddr_kgd;

#ifdef DDR_PAR_PATCH_INCLUDE
	ddr_kgd = otp_read_simple(0x138) & 0xF;
	serial_put_no_mmu('k');
	serial_put_no_mmu('g');
	serial_put_no_mmu('d');
	serial_put_no_mmu(':');
	serial_put_no_mmu(ddr_kgd + '0');
	serial_put_no_mmu('\r');
	serial_put_no_mmu('\n');
#endif

	/* set ddrc_clk */
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_SOURCE_SEL2) |= (1<<21);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_MPEG_CLK_INHIBIT2_NORM) &= ~((1<<2)|(1<<3));

	/* set ddrc_ports */
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DENALI_CONFIG0)=0xffffffff;

	/* reset ddrc */
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_MPEG_CLD_RST_NORM) |= (0x1);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_MPEG_CLD_RST_NORM) &= ~(0x1);

	//============set dram_config0-6: begin===================
	//clear config0-6
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG3)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG4)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG5)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG6)=0x0;

	//#1: config1[30:29], set ddr_version

#ifdef CONFIG_DDR3_BOTTOM
	ddr_version = 0x3;
#elif defined(CONFIG_DDR3_EXTERN)
	ddr_version = 0x2;  //not used
#elif defined(CONFIG_DDR2_BOTTOM)
	ddr_version = 0x1;
#elif defined(CONFIG_DDR2_TOP)
	ddr_version = 0x0;
#else
#error "DDR_POS error"
#endif

#ifdef DDR_PAR_PATCH_INCLUDE
#if defined(CONFIG_DDR2) && DDR_SIZE == 64
	/* when DDR is 2 and size is 64MB, ESMT JINHUA is BOTTOM */
	if (ddr_kgd == DDR_KGD_ESMT_JINHUA)
		ddr_version = 0x1;
#endif
#endif

#ifdef CHIP_BOARD_6706HX_BBT
	if (is_6706H1())
		ddr_version = 0x3; //6706H1 is DDR3 BOTTOM
#endif

	//#2: config0[2:0], tsel_feed
	tsel_feed = 0x1;

	//#3: config0[15], data_e_sel, choose the switch of the receiver in DDRIO
	//data_e_sel=0 means switch is controlled by DRAM_CONFIG0[14:11]
	data_e_sel = 0x0;

	//#4: ocd_pu&ocd_pd
	ocd_pu_clk = 8;
	ocd_pd_clk = 8;
	ocd_pu_cmd = 8;
	ocd_pd_cmd = 8;

	//#5: set output driver_strength of DDRIO in board_init.c
#ifdef CHIP_BOARD_6706HX_BBT
	if (is_6706H1())
		ddr_config_patch_6706H1();
	else
		ddr_config_patch();
#else
	ddr_config_patch();
#endif

	//#6: config0[31], dfi_cmd_control
	dfi_cmd_control = 0x1;

	//#7: config2[19:16], set Vref
	vref_set = 0x0;

	//#8: config3[1:0], set encry_delay
	cwl = (DENALI_CONFIG_CTL[5] >> 16) & 0x1F;
	encry_delay = (cwl - 4) / 2;

	//#9: config3[19], ddr_vref_en
	ddr_vref_en=0x0;

	//set DRAM_CONFIG
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0) |= (tsel_feed<<0) | (data_e_sel<<15) | (dfi_cmd_control<<31);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1) |= (ocd_pu_clk<<3) | (ocd_pd_clk<<7) | (ocd_pu_clk<<14) | (ocd_pd_clk<<18) | (ddr_version<<29);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2) |= (ocd_pu_cmd<<3) | (ocd_pd_cmd<<7) | (vref_set<<16);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG3) |= (encry_delay<<0) | (ddr_vref_en<<19);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG4) |= (ocd_pu_clk<<0) | (ocd_pd_clk<<4) | (ocd_pu_clk<<8) | (ocd_pd_clk<<12) | (ocd_pu_clk<<16) | (ocd_pd_clk<<20) | (ocd_pu_clk<<24) | (ocd_pd_clk<<28);
	//============set dram_config0-6: end===========

	for(i = 0;i < sizeof(DENALI_CONFIG_CTL)/sizeof(unsigned int); i++)
		*(volatile unsigned int *)Databahn_Reg(i) = DENALI_CONFIG_CTL[i];

	for(i = 0; i < sizeof(DENALI_CONFIG_PHY)/sizeof(unsigned int); i++)
		*(volatile unsigned int *)Databahn_Reg((i + 256)) = DENALI_CONFIG_PHY[i];

#ifdef DDR_PAR_PATCH_INCLUDE
	if (ddr_kgd > 0) {
		for (i = 0; i < sizeof(DDR_PAR_PATCH_ARRAY)/sizeof(struct ddr_patch); i++) {
			if (ddr_kgd == DDR_PAR_PATCH_ARRAY[i].kgd_type)
				*(volatile unsigned int *)DDR_PAR_PATCH_ARRAY[i].addr = DDR_PAR_PATCH_ARRAY[i].value;
		}
	}
#endif
#ifdef CHIP_BOARD_Cygnus_X5
	if (is_6705()) {
		serial_put_no_mmu('5');
		for(i = 0;i < sizeof(DENALI_CONFIG_CTL_2)/sizeof(unsigned int); i++)
			*(volatile unsigned int *)Databahn_Reg(i) = DENALI_CONFIG_CTL_2[i];

		for(i = 0; i < sizeof(DENALI_CONFIG_PHY_2)/sizeof(unsigned int); i++)
			*(volatile unsigned int *)Databahn_Reg((i + 256)) = DENALI_CONFIG_PHY_2[i];
#ifdef DDR_SEC_PAR_PATCH_INCLUDE
		if (ddr_kgd > 0) {
			for (i = 0; i < sizeof(DDR_SEC_PAR_PATCH_ARRAY)/sizeof(struct ddr_patch); i++)
				if (ddr_kgd == DDR_SEC_PAR_PATCH_ARRAY[i].kgd_type)
					*(volatile unsigned int *)DDR_SEC_PAR_PATCH_ARRAY[i].addr = DDR_SEC_PAR_PATCH_ARRAY[i].value;
		}
#endif
	}
#elif defined(CHIP_BOARD_6706HX_BBT)
	if (is_6706H1()) {
		serial_put_no_mmu('1');
		for(i = 0;i < sizeof(DENALI_CONFIG_CTL_2)/sizeof(unsigned int); i++)
			*(volatile unsigned int *)Databahn_Reg(i) = DENALI_CONFIG_CTL_2[i];

		for(i = 0; i < sizeof(DENALI_CONFIG_PHY_2)/sizeof(unsigned int); i++)
			*(volatile unsigned int *)Databahn_Reg((i + 256)) = DENALI_CONFIG_PHY_2[i];
#ifdef DDR_SEC_PAR_PATCH_INCLUDE
		if (ddr_kgd > 0) {
			for (i = 0; i < sizeof(DDR_SEC_PAR_PATCH_ARRAY)/sizeof(struct ddr_patch); i++)
				if (ddr_kgd == DDR_SEC_PAR_PATCH_ARRAY[i].kgd_type)
					*(volatile unsigned int *)DDR_SEC_PAR_PATCH_ARRAY[i].addr = DDR_SEC_PAR_PATCH_ARRAY[i].value;
		}
#endif
	}
#endif

	Databahn_Config();

	while(!Databahn_isReady());
}

void Databahn_SetParameters(struct reg_param *regs, int count)
{
	int i;

	for (i=0; i < count; i++)
		SetRegisterField(Databahn_Reg(regs[i].reg), regs[i].offset, regs[i].width, regs[i].value);
}

